{
  "html": "<section data-ui-unit="booking">
  <div class="booking-host">
    <span class="booking-studio">틈 도자기 스튜디오</span>
    <span class="booking-meta">재료와 도구 포함 · 완성품 소성 후 수령</span>
  </div>

  <div class="booking-action-row">
    <button id="favorite" type="button" aria-label="수업 찜하기" aria-pressed="false">
      <img src="assets/icons/Heart.svg" alt="" width="24" height="24">
    </button>
    <button id="book" type="button">일정 선택하고 예약하기</button>
  </div>

  <p class="booking-note">일정을 선택한 뒤 예약 내용을 확인할 수 있어요.</p>
</section>",
  "css": ".booking-host {
  padding: 20px 0;
  border-top: 1px solid #ededf0;
}

.booking-studio {
  display: block;
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  margin-bottom: 4px;
}

.booking-meta {
  display: block;
  font-size: 14px;
  color: #60606a;
  line-height: 1.4;
}

.booking-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  margin-top: 20px;
}

#favorite {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: transparent;
  border: none;
  padding: 0;
  color: #60606a;
}

#favorite img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

#book {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 52px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  border-radius: 6px;
  border: none;
}

.booking-note {
  margin-top: 12px;
  font-size: 14px;
  line-height: 1.6;
  color: #60606a;
}

/* Interactive States */
#favorite:hover {
  background-color: #f5f5f7;
  color: #202024;
}

#favorite:active {
  transform: scale(0.95);
}

#book:hover {
  opacity: 0.9;
}

#book:active {
  background-color: #3e36b5;
}"
}
